export async function main(ns) {
  const servers = new Set(['home']);
  const toVisit = ['home'];

  // BFS scan to discover all reachable servers
  while (toVisit.length > 0) {
    const current = toVisit.shift();
    const neighbors = ns.scan(current);
    for (const neighbor of neighbors) {
      if (!servers.has(neighbor)) {
        servers.add(neighbor);
        toVisit.push(neighbor);
      }
    }
  }

  // Find best target: servers with root access and maxMoney > 0
  let best = null;
  let bestMoney = 0;

  for (const server of servers) {
    if (ns.hasRootAccess(server)) {
      const maxMoney = ns.getServerMaxMoney(server);
      if (maxMoney > bestMoney) {
        bestMoney = maxMoney;
        best = server;
      }
    }
  }

  if (!best) {
    ns.tprint('No servers with root access found');
    return;
  }

  ns.tprint(`Targeting ${best} with max money $${bestMoney}`);

  // Infinite harvesting loop
  while (true) {
    const security = ns.getServerSecurityLevel(best);
    const money = ns.getServerMoneyAvailable(best);
    const maxMoney = ns.getServerMaxMoney(best);

    if (security > 2) {
      await ns.weaken(best);
    } else if (money < 0.8 * maxMoney) {
      await ns.grow(best);
    } else {
      await ns.hack(best);
    }
  }
}

