/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const queue = ['home'];
  const candidates = [];

  // BFS to scan all reachable servers
  while (queue.length > 0) {
    const server = queue.shift();
    if (visited.has(server)) continue;
    visited.add(server);

    // Check if we have root access
    if (ns.hasRootAccess(server) && server !== 'home') {
      const maxMoney = ns.getServerMaxMoney(server);
      if (maxMoney > 0) {
        candidates.push({ name: server, maxMoney });
      }
    }

    // Add neighbors to queue
    const neighbors = ns.scan(server);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        queue.push(neighbor);
      }
    }
  }

  // Pick target with highest max money
  if (candidates.length === 0) {
    ns.tprint('No valid targets found');
    return;
  }

  candidates.sort((a, b) => b.maxMoney - a.maxMoney);
  const target = candidates[0].name;
  ns.tprint(`Target selected: ${target} with max money $${candidates[0].maxMoney}`);

  // Infinite harvesting loop
  while (true) {
    const security = ns.getServerSecurityLevel(target);
    const available = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);

    if (security > 2) {
      await ns.weaken(target);
    } else if (available < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  // BFS to discover all accessible servers
  const queue = ['home'];
  const visited = new Set(['home']);
  const candidates = [];

  while (queue.length > 0) {
    const server = queue.shift();
    const neighbors = ns.scan(server);

    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);

        // Check if we have root access and server has money
        if (ns.hasRootAccess(neighbor) && ns.getServerMaxMoney(neighbor) > 0 && neighbor !== 'home') {
          const maxMoney = ns.getServerMaxMoney(neighbor);
          candidates.push({ name: neighbor, maxMoney });
        }
      }
    }
  }

  // Sort by maxMoney descending and pick the best
  candidates.sort((a, b) => b.maxMoney - a.maxMoney);

  if (candidates.length === 0) {
    ns.tprint('ERROR: No suitable servers found!');
    return;
  }

  const target = candidates[0].name;
  ns.tprint(`TARGET: ${target} (max money: $${candidates[0].maxMoney})`);

  // Infinite harvesting loop
  while (true) {
    const security = ns.getServerSecurityLevel(target);
    const available = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);
    const threshold = maxMoney * 0.75;

    if (security > 2) {
      ns.tprint(`[${new Date().toISOString()}] WEAKEN: sec=${security.toFixed(2)}`);
      await ns.weaken(target);
    } else if (available < threshold) {
      ns.tprint(`[${new Date().toISOString()}] GROW: money=${available}/${maxMoney}`);
      await ns.grow(target);
    } else {
      ns.tprint(`[${new Date().toISOString()}] HACK: money=${available}/${maxMoney}`);
      await ns.hack(target);
    }
  }
}
